import { execFile } from 'node:child_process';
import { relative, sep } from 'node:path';
import { promisify } from 'node:util';
import type { PageIndexInfo, RspressPlugin } from '@rspress/core';

const execFileAsync = promisify(execFile);

// rspress/docs is generated by migrate.py, so its own git history only holds
// migration commits. Resolve each page back to its Docusaurus source instead.
// Keep in sync with the SOURCES / *_SOURCE_* constants of migrate.py.
const VERSIONED_SOURCE: Record<string, (version: string) => string> = {
  en: (version) => `versioned_docs/version-${version}`,
  fr: (version) => `i18n/fr/docusaurus-plugin-content-docs/version-${version}`,
};
const STANDALONE_SOURCE: Record<string, (section: string) => string> = {
  en: (section) => section,
  fr: (section) => `i18n/fr/docusaurus-plugin-content-docs-${section}/current`,
};
const STANDALONE_SECTIONS = ['pp', 'cloud', 'logmanagement', 'experience-monitoring'];
const VERSION_RE = /^\d+\.\d+$/;

// Field set by rspress' built-in last-updated plugin, missing from the public type.
interface PageDataWithLastUpdated extends PageIndexInfo {
  lastUpdatedTime?: string;
}

function sourceCandidates(docsRelPath: string): string[] {
  const [lang, section, ...rest] = docsRelPath.split(sep);
  if (!lang || !section || rest.length === 0) return [];
  let base: string | undefined;
  if (VERSION_RE.test(section)) base = VERSIONED_SOURCE[lang]?.(section);
  else if (STANDALONE_SECTIONS.includes(section)) base = STANDALONE_SOURCE[lang]?.(section);
  if (!base) return [];
  // migrate.py may turn a .md source into .mdx (JSX detection), so try both.
  const stem = rest.join('/').replace(/\.mdx?$/, '');
  return [`${base}/${stem}.md`, `${base}/${stem}.mdx`];
}

async function collectCommitTimes(repoRoot: string): Promise<Map<string, number>> {
  const paths = ['versioned_docs', 'i18n/fr', ...STANDALONE_SECTIONS];
  const times = new Map<string, number>();
  try {
    const { stdout } = await execFileAsync(
      'git',
      ['-c', 'core.quotePath=false', 'log', '--format=%x00%ct', '--name-only', '--no-renames', '--', ...paths],
      { cwd: repoRoot, maxBuffer: 1024 * 1024 * 1024 },
    );
    let current = 0;
    for (const line of stdout.split('\n')) {
      if (line.startsWith('\0')) current = Number(line.slice(1)) * 1000;
      else if (line && !times.has(line)) times.set(line, current);
    }
  } catch {
    // Not a git checkout (or shallow history): keep rspress' own dates.
  }
  return times;
}

export function pluginLastUpdatedFromSource(docsRoot: string, repoRoot: string): RspressPlugin {
  let times: Promise<Map<string, number>> | undefined;
  return {
    name: 'centreon:last-updated-from-source',
    beforeBuild() {
      times = collectCommitTimes(repoRoot);
    },
    async extendPageData(pageData: PageDataWithLastUpdated) {
      const lookup = await (times ??= collectCommitTimes(repoRoot));
      const rel = relative(docsRoot, pageData._filepath);
      const timestamp = sourceCandidates(rel)
        .map((candidate) => lookup.get(candidate))
        .find(Boolean);
      if (!timestamp) return;
      // Same format as Docusaurus' "Last updated on" (e.g. "Oct 9, 2025").
      pageData.lastUpdatedTime = new Intl.DateTimeFormat(pageData.lang || 'en', {
        day: 'numeric',
        month: 'short',
        year: 'numeric',
        timeZone: 'UTC',
      }).format(timestamp);
    },
  };
}
